// translateCPUProfileTI parses binary CPU profiling stack trace data
// generated by runtime.CPUProfile() into a profile struct.
// This is only used for testing. Real conversions stream the
// data into the profileBuilder as it becomes available.
//
// count is the number of records in data.
func translateCPUProfileTI(data []uint64, count int, needTangoInfo bool) (*profile.Profile, error) {
	var buf bytes.Buffer
	b := newProfileBuilder(&buf)
	b.needTangoInfo = needTangoInfo
	tags := make([]unsafe.Pointer, count)
	if err := b.addCPUData(data, tags); err != nil {
		return nil, err
	}
	b.build()
	return profile.Parse(&buf)
}

// Test whether TangoInfo is generated.
func TestTangoInfo(t *testing.T) {
	checkTangoInfo(t, false)
	checkTangoInfo(t, true)

	oldEnv1 := os.Getenv("GOGC")
	oldEnv2 := os.Getenv("MY_CPU_LIMIT")

	os.Setenv("GOGC", "100")
	checkTangoInfo(t, true)

	os.Setenv("GOGC", "random'value,xxx")
	os.Setenv("MY_CPU_LIMIT", "50")
	checkTangoInfo(t, true)

	// '"' will be encoded as '\"', which works correctly.
	// Don't test it for now.
	//os.Setenv("GOGC", "\"")
	//checkTangoInfo(t, true)

	os.Setenv("GOGC", oldEnv1)
	os.Setenv("MY_CPU_LIMIT", oldEnv2)
	checkTangoInfo(t, true)
}

func checkTangoInfo(t *testing.T, needTangoInfo bool) {
	b := []uint64{3, 0, 500} // empty profile at 500 Hz (2ms sample period)
	p, err := translateCPUProfileTI(b, 1, needTangoInfo)
	if err != nil {
		t.Fatalf("translateCPUProfileTI: %v", err)
	}

	found := false
	var cmt string
	for _, cmt = range p.Comments {
		found = strings.Contains(cmt, tangoInfoTag) // looking for the tag
		t.Logf("Comment: %s", cmt)
		if found {
			break
		}
	}

	if found != needTangoInfo {
		t.Fatalf("Found TangoInfo:%t, should found TangoInfo:%t", found, needTangoInfo)
	}
	if found {
		checkMsgJson(t, cmt)
	}
}

// Don't reuse the code in proto_tango.go.
// Uses hard-coded string instead to make sure we generate the correct message.
// Need to update this test once the format is changed.
var tangoTestKv = []string{
	"\"TI_VERSION\":\"" + tangoInfoVersion + "\"",
	"\"BVERSION\":\"" + runtime.BVersion() + "\"",
	"\"GOROOT\":\"" + runtime.GOROOT() + "\"",
	"\"GOMAXPROCS\":\"" + strconv.Itoa(runtime.GOMAXPROCS(-1)) + "\"",
}

func checkMsgJson(t *testing.T, msg string) {
	for _, str := range tangoTestKv {
		if !strings.Contains(msg, str) {
			t.Fatalf("Didn't find:%s within %s", str, msg)
		}
	}

	for _, envName := range tangoInfoEnvs {
		if envVal := os.Getenv(envName); envVal != "" {
			str := fmt.Sprintf("\"%s\":\"%s\"", envName, envVal)
			if !strings.Contains(msg, str) {
				t.Fatalf("Didn't find:%s within %s", str, msg)
			}
		}
	}
}
